__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),e.regulamento=function(o){return[{titulo:"1. A liga",itens:["O T\xeanis Rondon\xf3polis \xe9 uma liga anual de t\xeanis simples, com ranking por pontos nas categorias 1, 2, 3 e Feminino.","Mensalidade de R$ 60,00, com d\xe9bito autom\xe1tico todo m\xeas pelo Pix Autom\xe1tico ou pelo cart\xe3o de cr\xe9dito (ou, se preferir, Pix ou boleto pago m\xeas a m\xeas).","A organiza\xe7\xe3o aprova cada inscri\xe7\xe3o e define a categoria pelo n\xedvel t\xe9cnico do jogador."]},{titulo:"2. Pontua\xe7\xe3o",itens:[`Vit\xf3ria por 2\xd70: +${o.pts_vitoria_2x0} pontos.`,`Vit\xf3ria por 2\xd71 (no super tie-break): +${o.pts_vitoria_2x1} pontos.`,`Derrota por 1\xd72: +${o.pts_derrota_1x2} pontos.`,`Derrota por 0\xd72: +${o.pts_derrota_0x2} pontos. Quem joga sempre pontua, para estimular os jogos.`,`WO \u2014 n\xe3o compareceu e n\xe3o avisou: ${o.pts_wo} pontos; o advers\xe1rio recebe a vit\xf3ria por 2\xd70.`,`Falta com aviso (avisou o advers\xe1rio com pelo menos 2h de anteced\xeancia): ${o.pts_fav} pontos; o advers\xe1rio recebe a vit\xf3ria por 2\xd70.`,"Abandono durante o jogo: quem abandona n\xe3o pontua; o advers\xe1rio recebe a vit\xf3ria por 2\xd70.","Desempate no ranking: mais vit\xf3rias, depois saldo de sets, depois saldo de games."]},{titulo:"3. Desafios",itens:[`Cada jogador pode desafiar quem est\xe1 at\xe9 ${o.posicoes_acima} posi\xe7\xf5es acima dele, na mesma categoria.`,"Cada jogador s\xf3 pode ter um desafio em aberto por vez (enviado ou recebido).",`O desafiado tem ${o.dias_para_responder} dias para aceitar e marcar data, hor\xe1rio e local. Sem resposta, perde por WO.`,"N\xe3o \xe9 permitido recusar desafio: a recusa conta como WO.",`O jogo deve acontecer em at\xe9 ${o.dias_para_jogar} dias do desafio. Se n\xe3o acontecer, o desafio expira sem pontos e a organiza\xe7\xe3o pode aplicar WO a quem deu causa.`,"O desafiante pode cancelar o desafio enquanto ele n\xe3o for aceito.","Com mensalidade atrasada h\xe1 mais de "+o.dias_tolerancia_pgto+" dias, o jogador n\xe3o pode desafiar, mas continua podendo ser desafiado."]},{titulo:"4. Confrontos repetidos",itens:[`Revanche entre os mesmos jogadores s\xf3 depois de ${o.dias_entre_revanches} dias do \xfaltimo jogo.`,"Limite de confrontos entre o mesmo par em qualquer per\xedodo de 3 meses, conforme o tamanho da categoria:","\u2022 at\xe9 8 jogadores ativos: at\xe9 3 jogos;","\u2022 de 9 a 19 jogadores: at\xe9 2 jogos;","\u2022 20 ou mais jogadores: 1 jogo.","Os limites foram definidos por simula\xe7\xe3o da temporada: mant\xeam pelo menos ~94% do volume de jogos e impedem que a mesma dupla se enfrente 4 ou mais vezes no trimestre."]},{titulo:"5. Jogos e placar",itens:["Formato: 2 sets com tie-break em 6\xd76; empate em 1\xd71 decide em super tie-break de 10 pontos.","Os pr\xf3prios jogadores marcam as bolas e a contagem; na d\xfavida, o ponto \xe9 repetido.",`Qualquer um dos dois lan\xe7a o placar no app; o outro confirma. Sem resposta em ${o.horas_para_confirmar}h, o placar \xe9 confirmado automaticamente.`,"Placar contestado vai para a organiza\xe7\xe3o, que decide e lan\xe7a o resultado final.","Toler\xe2ncia de atraso: 15 minutos. Depois disso, quem compareceu pode lan\xe7ar WO."]},{titulo:"6. Elimina\xe7\xe3o",itens:["\xc9 eliminado da temporada quem acumular 2 WOs, ou 1 WO e 2 faltas com aviso, ou 3 faltas com aviso."]},{titulo:"7. Finals",itens:["A contagem de pontos do ranking fecha uma semana antes do Finals.","Os 8 primeiros de cada categoria jogam o Finals em mata-mata: 1\xba\xd78\xba, 4\xba\xd75\xba, 2\xba\xd77\xba e 3\xba\xd76\xba; semifinais e final.",`B\xf4nus somado \xe0 pontua\xe7\xe3o do ano: campe\xe3o +${o.bonus_finals_campeao}, vice +${o.bonus_finals_vice}, semifinalistas +${o.bonus_finals_semi}, quartas de final +${o.bonus_finals_quartas}.`,"O campe\xe3o da liga \xe9 o 1\xba colocado do ranking depois de somado o b\xf4nus do Finals."]},{titulo:"8. Pr\xeamio",itens:["70% de tudo o que for arrecadado em mensalidades de cada categoria forma o pr\xeamio daquela categoria.","O pr\xeamio \xe9 dividido em 70% para o campe\xe3o e 30% para o vice-campe\xe3o.","O valor acumulado aparece em tempo real na tela de ranking."]},{titulo:"9. Subida e descida",itens:[`Ao fim do ano, os ${o.sobem_fim_ano} primeiros das categorias 2 e 3 sobem uma categoria.`,`Os ${o.descem_fim_ano} \xfaltimos das categorias 1 e 2 descem uma categoria, para manter o equil\xedbrio do n\xfamero de jogadores.`,"Na nova temporada a ordem \xe9 mantida com pontos de largada: quem sobe entra no fim da nova categoria; quem desce entra no topo."]},{titulo:"10. Casos omissos",itens:["Casos n\xe3o previstos ser\xe3o decididos pela organiza\xe7\xe3o da liga, em \xfaltima inst\xe2ncia."]}]}},844,[]);